<?php
namespace App\Http\Controllers;
use App\Models\ExamResult; use App\Models\Student; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class ExamResultController extends Controller {
 private function grade(float $percent): array { return match(true){$percent>=80=>['A+',4.00],$percent>=75=>['A',3.75],$percent>=70=>['A-',3.50],$percent>=65=>['B+',3.25],$percent>=60=>['B',3.00],$percent>=55=>['B-',2.75],$percent>=50=>['C+',2.50],$percent>=45=>['C',2.25],$percent>=40=>['D',2.00],default=>['F',0.00]}; }
 public function index(Request $request){ $q=ExamResult::with('student')->latest(); foreach(['student_id','exam_name','exam_year','semester'] as $f) if($request->filled($f)) $q->where($f,$request->$f); $results=$q->paginate(25)->withQueryString(); $students=Student::where('status','Active')->orderBy('technology')->orderBy('semester')->orderBy('student_id')->get(); $groups=ExamResult::selectRaw('student_id, exam_name, exam_year, semester, SUM(credit * grade_point) / NULLIF(SUM(credit),0) as gpa, COUNT(*) as subjects')->groupBy('student_id','exam_name','exam_year','semester')->with('student')->orderByDesc('exam_year')->limit(100)->get(); $technologies=Student::select('technology')->distinct()->orderBy('technology')->pluck('technology'); $semesters=Student::select('semester')->distinct()->orderBy('semester')->pluck('semester'); return view('results.index',compact('results','students','groups','technologies','semesters')); }
 public function store(Request $request){ $data=$request->validate(['technology'=>'required|string','semester'=>'required|string','exam_name'=>'required|string|max:120','exam_year'=>'required|string|max:10','subject_code'=>'nullable|string|max:40','subject_name'=>'required|string|max:150','credit'=>'required|numeric|min:0.25|max:20','full_marks'=>'required|numeric|min:1|max:10000','pass_marks'=>'required|numeric|min:0|lte:full_marks','marks'=>'required|array|min:1','marks.*'=>'nullable|numeric|min:0']); $students=Student::where('status','Active')->where('technology',$data['technology'])->where('semester',$data['semester'])->get()->keyBy('id'); $validMarks=collect($data['marks'])->filter(fn($m)=>$m!==null && $m!==''); if($validMarks->isEmpty()) return back()->withErrors(['marks'=>'কমপক্ষে একজন শিক্ষার্থীর নম্বর দিন।'])->withInput(); foreach($validMarks as $id=>$mark){ if(!$students->has((int)$id)) continue; if((float)$mark>(float)$data['full_marks']) return back()->withErrors(['marks'=>'প্রাপ্ত নম্বর Full Marks-এর বেশি হতে পারবে না।'])->withInput(); }
 DB::transaction(function() use($data,$validMarks,$students){ foreach($validMarks as $id=>$mark){ if(!$students->has((int)$id)) continue; $percent=((float)$mark/(float)$data['full_marks'])*100; [$letter,$point]=$this->grade($percent); ExamResult::updateOrCreate(['student_id'=>$id,'exam_name'=>$data['exam_name'],'exam_year'=>$data['exam_year'],'semester'=>$data['semester'],'subject_code'=>$data['subject_code']??null],['subject_name'=>$data['subject_name'],'credit'=>$data['credit'],'marks'=>$mark,'full_marks'=>$data['full_marks'],'pass_marks'=>$data['pass_marks'],'letter_grade'=>(float)$mark<(float)$data['pass_marks']?'F':$letter,'grade_point'=>(float)$mark<(float)$data['pass_marks']?0:$point]); }}); return redirect()->route('results.index')->with('success',$validMarks->count().' জন শিক্ষার্থীর নম্বর সংরক্ষণ হয়েছে।'); }
 public function destroy(ExamResult $result){$result->delete();return back()->with('success','ফলাফল মুছে ফেলা হয়েছে।');}
}
